import { expiryState } from '../src/lib/fifo';
import { joinParts } from '../src/lib/parts';
import { withStatus } from '../src/lib/stock';
import type { Pending, Product } from '../src/lib/types';
import { b64url, sendPush, type PushSub } from './push';

interface Env {
  DB: D1Database;
}

/** VAPID key pair: generated by the Worker on first use and kept in D1 (no secret to configure). */
export async function vapidKeys(env: Env): Promise<{ publicKey: string; privateJwk: JsonWebKey }> {
  const row = await env.DB.prepare("SELECT value FROM app_keys WHERE name = 'vapid'").first<{ value: string }>();
  if (row) return JSON.parse(row.value);
  const k = (await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify'])) as CryptoKeyPair;
  const keys = {
    publicKey: b64url((await crypto.subtle.exportKey('raw', k.publicKey)) as ArrayBuffer),
    privateJwk: (await crypto.subtle.exportKey('jwk', k.privateKey)) as JsonWebKey,
  };
  await env.DB.prepare("INSERT OR IGNORE INTO app_keys (name, value) VALUES ('vapid', ?)").bind(JSON.stringify(keys)).run();
  // Another request may have won the race — read back what is stored.
  const stored = await env.DB.prepare("SELECT value FROM app_keys WHERE name = 'vapid'").first<{ value: string }>();
  return stored ? JSON.parse(stored.value) : keys;
}

const pl = (n: number, one: string, few: string, many: string) => {
  if (n === 1) return one;
  const d = n % 10;
  const h = n % 100;
  return d >= 2 && d <= 4 && (h < 12 || h > 14) ? few : many;
};

/** What deserves a reminder today for one user (null = nothing to say). */
export async function reminderFor(env: Env, userId: string): Promise<{ title: string; body: string; url: string } | null> {
  const rows = (await env.DB.prepare('SELECT part, data FROM warehouse_parts WHERE user_id = ?').bind(userId).all<{ part: string; data: string }>()).results;
  if (!rows.length) return null;
  const state = joinParts(Object.fromEntries(rows.map((r) => [r.part, JSON.parse(r.data)]))) as {
    products: Product[];
    pending?: Pending[];
    training?: unknown;
  };
  const incoming = new Map<string, number>();
  for (const x of state.pending ?? []) incoming.set(x.productId, (incoming.get(x.productId) ?? 0) + x.qty);
  const products = state.products.filter((p) => !p.archived).map((p) => withStatus(p, incoming.get(p.id) ?? 0));
  let expired = 0;
  let soon = 0;
  for (const p of products)
    for (const l of p.lots ?? []) {
      const s = expiryState(l);
      if (s === 'expired') expired++;
      else if (s === 'soon') soon++;
    }
  const toOrder = products.filter((p) => p.needs).length;
  const parts = [
    expired && `${expired} ${pl(expired, 'partia', 'partie', 'partii')} po terminie`,
    soon && `${soon} z kończącym się terminem`,
    toOrder && `${toOrder} ${pl(toOrder, 'produkt', 'produkty', 'produktów')} do zamówienia`,
    state.training && 'szkolenie czeka na rozliczenie',
  ].filter(Boolean) as string[];
  if (!parts.length) return null;
  return {
    title: expired ? 'Magazyn: sprawdź terminy' : 'Magazyn: przypomnienie',
    body: parts.join(' · '),
    url: expired || soon ? '/terminy' : toOrder ? '/zamowienia' : '/szkolenie',
  };
}

/** Sends to every subscription of a user; drops subscriptions the push service says are gone. */
export async function notifyUser(env: Env, userId: string, message: { title: string; body: string; url: string }, subject: string) {
  const keys = await vapidKeys(env);
  const subs = (await env.DB.prepare('SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE user_id = ?').bind(userId).all<PushSub>()).results;
  const statuses: number[] = [];
  for (const sub of subs) {
    let status = 0;
    try {
      status = await sendPush(sub, { ...message, tag: 'magazyn-daily' }, { ...keys, subject });
    } catch {
      status = 0;
    }
    statuses.push(status);
    if (status === 404 || status === 410) await env.DB.prepare('DELETE FROM push_subscriptions WHERE endpoint = ?').bind(sub.endpoint).run();
  }
  return { sent: statuses.filter((s) => s >= 200 && s < 300).length, statuses };
}

/** Daily cron: remind every user with a subscription, if there is something to say. */
export async function dailyReminders(env: Env, subject: string) {
  const users = (await env.DB.prepare('SELECT DISTINCT user_id FROM push_subscriptions').all<{ user_id: string }>()).results;
  for (const { user_id } of users) {
    const msg = await reminderFor(env, user_id);
    if (msg) await notifyUser(env, user_id, msg, subject);
  }
}
